// Free questions: per topic, one easy, one hard and two medium, so they spread across topics and difficulties.
function pickFree(list) {
  const out = [];
  for (const t of [...new Set(list.map((q) => q.t))]) {
    const idx = list.map((q, i) => [q, i]).filter(([q]) => q.t === t);
    const by = (d) => idx.filter(([q]) => q.d === d).map(([, i]) => i);
    out.push(by(1)[0], by(3)[0], ...by(2).slice(0, 2));
  }
  return out;
}

export default {
  waec: { list: waecList, free: pickFree(waecList) },
  neco: { list: necoList, free: pickFree(necoList) },
};
